// Crypto___Security_Engine_apb: APB4 register wrapper around Crypto___Security_Engine_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Crypto___Security_Engine.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Crypto___Security_Engine.md
// ============================================================================
module Crypto___Security_Engine_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq
);
  localparam logic [31:0] ID_VALUE = 32'h53480200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [23:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd24) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_msg_we;
  logic [1:0]    c_msg_widx;
  logic [127:0]  c_msg;
  logic          c_key_we;
  logic [1:0]    c_key_widx;
  logic [127:0]  c_key;
  logic [6:0]    c_msg_len;
  logic          c_start;
  logic          c_mode;
  logic          c_busy;
  logic          c_done;
  logic [255:0]  c_digest;
  logic          c_irq;
  Crypto___Security_Engine_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .msg_we(c_msg_we),
    .msg_widx(c_msg_widx),
    .msg(c_msg),
    .key_we(c_key_we),
    .key_widx(c_key_widx),
    .key(c_key),
    .msg_len(c_msg_len),
    .start(c_start),
    .mode(c_mode),
    .busy(c_busy),
    .done(c_done),
    .digest(c_digest),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_MSG0;   // 12'h014 MSG0
  logic [31:0] r_MSG1;   // 12'h018 MSG1
  logic [31:0] r_MSG2;   // 12'h01C MSG2
  logic [31:0] r_MSG3;   // 12'h020 MSG3
  logic [31:0] r_KEY0;   // 12'h024 KEY0
  logic [31:0] r_KEY1;   // 12'h028 KEY1
  logic [31:0] r_KEY2;   // 12'h02C KEY2
  logic [31:0] r_KEY3;   // 12'h030 KEY3
  logic [11:0] r_CTRL;   // 12'h034 CTRL
  logic [2:0] p_CMD;   // 12'h038 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_MSG0 <= 32'h0;
      r_MSG1 <= 32'h0;
      r_MSG2 <= 32'h0;
      r_MSG3 <= 32'h0;
      r_KEY0 <= 32'h0;
      r_KEY1 <= 32'h0;
      r_KEY2 <= 32'h0;
      r_KEY3 <= 32'h0;
      r_CTRL <= 12'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_MSG0 <= (r_MSG0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6]) r_MSG1 <= (r_MSG1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_MSG2 <= (r_MSG2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_MSG3 <= (r_MSG3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_KEY0 <= (r_KEY0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_KEY1 <= (r_KEY1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[11]) r_KEY2 <= (r_KEY2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_KEY3 <= (r_KEY3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_CTRL <= (r_CTRL & ~wmask[11:0]) | (PWDATA[11:0] & wmask[11:0]);
      p_CMD <= (wr && hit[14]) ? PWDATA[2:0] & wmask[2:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_msg[31:0] = r_MSG0[31:0];
  assign c_msg[63:32] = r_MSG1[31:0];
  assign c_msg[95:64] = r_MSG2[31:0];
  assign c_msg[127:96] = r_MSG3[31:0];
  assign c_key[31:0] = r_KEY0[31:0];
  assign c_key[63:32] = r_KEY1[31:0];
  assign c_key[95:64] = r_KEY2[31:0];
  assign c_key[127:96] = r_KEY3[31:0];
  assign c_msg_len = r_CTRL[6:0];
  assign c_mode = r_CTRL[7:7];
  assign c_msg_widx = r_CTRL[9:8];
  assign c_key_widx = r_CTRL[11:10];
  assign c_msg_we = p_CMD[0:0];
  assign c_key_we = p_CMD[1:1];
  assign c_start = p_CMD[2:2];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_MSG0);
      10'd6: apb_rdata = 32'(r_MSG1);
      10'd7: apb_rdata = 32'(r_MSG2);
      10'd8: apb_rdata = 32'(r_MSG3);
      10'd9: apb_rdata = 32'(r_KEY0);
      10'd10: apb_rdata = 32'(r_KEY1);
      10'd11: apb_rdata = 32'(r_KEY2);
      10'd12: apb_rdata = 32'(r_KEY3);
      10'd13: apb_rdata = 32'(r_CTRL);
      10'd15: apb_rdata = 32'({c_digest[31:0]});
      10'd16: apb_rdata = 32'({c_digest[63:32]});
      10'd17: apb_rdata = 32'({c_digest[95:64]});
      10'd18: apb_rdata = 32'({c_digest[127:96]});
      10'd19: apb_rdata = 32'({c_digest[159:128]});
      10'd20: apb_rdata = 32'({c_digest[191:160]});
      10'd21: apb_rdata = 32'({c_digest[223:192]});
      10'd22: apb_rdata = 32'({c_digest[255:224]});
      10'd23: apb_rdata = 32'({c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
